import re

def parse_duration(input_str: str) -> int:
    if not input_str:
        raise ValueError("Empty duration string")

    components = re.findall(r'(\d+)([hms])', input_str)

    if not components:
        raise ValueError("No valid duration components found")

    full_match_str = "".join(f"{val}{unit}" for val, unit in components)
    if full_match_str != input_str:
        raise ValueError("Invalid duration format or unknown characters")

    conversion_data = {
        'h': {'order': 1, 'factor': 3600},
        'm': {'order': 2, 'factor': 60},
        's': {'order': 3, 'factor': 1}
    }

    accumulated_seconds = 0
    previous_order = 0
    captured_units = set()

    for amount, unit_char in components:
        metadata = conversion_data[unit_char]
        current_order = metadata['order']

        if unit_char in captured_units:
            raise ValueError(f"Repeated unit: {unit_char}")

        if current_order <= previous_order:
            raise ValueError(f"Units out of order: {unit_char}")

        captured_units.add(unit_char)
        previous_order = current_order
        accumulated_seconds += int(amount) * metadata['factor']

    return accumulated_seconds

