SET_OF_START_CHARS = frozenset(MAP_CLOSER_TO_OPENER.values())


def is_balanced(text: str) -> bool:
    """
    Determines if the brackets in the provided string are correctly nested.

    Supports (), [], and {}. All other characters are bypassed.
    """
    items_to_match = []

    for symbol in text:
        if symbol in SET_OF_START_CHARS:
            items_to_match.append(symbol)
        elif symbol in MAP_CLOSER_TO_OPENER:
            if items_to_match:
                last_opened = items_to_match.pop()
                if last_opened != MAP_CLOSER_TO_OPENER[symbol]:
                    return False
            else:
                return False

    return len(items_to_match) == 0

