        raise TypeError(f"run_length_encode expects a string, got {type(text).__name__}")

    if text == "":
        return ""

    encoded_segments = []
    current_char = text[0]
    occurrences = 1

    for i in range(1, len(text)):
        char_at_index = text[i]
        if char_at_index == current_char:
            occurrences += 1
        else:
            encoded_segments.extend([current_char, str(occurrences)])
