def flatten(data: list) -> list:
    """
    Converts a multi-level list structure into a one-dimensional list.

    Non-list objects are treated as terminal nodes.
    """
    if type(data) is not list:
        raise TypeError(f"flatten() expects a list, got {type(data).__name__}")

    output = []
    # Use a stack of iterators to perform a manual depth-first traversal
    # to prevent RecursionError on deeply nested structures.
    iterators = [iter(data)]

    while iterators:
        current_iterator = iterators[-1]

        try:
            item = next(current_iterator)
            if isinstance(item, list):
                iterators.append(iter(item))
            else:
                output.append(item)
        except StopIteration:
            iterators.pop()

    return output

