    # Return empty dict for empty input
    if not raw_data:
        return {}

    parsed_map: dict[str, list[str]] = {}

    for part in raw_data.split('&'):
        if part:
            # Determine key-value pair via splitting
            if '=' in part:
                k, v = part.split('=', 1)
            else:
                k, v = part, ''

            # Decode URL percent-encoding and '+' signs
            decoded_key = unquote_plus(k)
            decoded_val = unquote_plus(v)

            # Group values under their respective keys
            if decoded_key not in parsed_map:
                parsed_map[decoded_key] = []
            parsed_map[decoded_key].append(decoded_val)

    return parsed_map

