        return []

    # Ensure all ranges are logically sound
    for s, e in intervals:
        if s > e:
            raise ValueError(f"Invalid interval ({s}, {e}): start must be <= end")

    # Sort the input to allow linear processing
    sorted_data = sorted(intervals)

    combined_ranges = []

    for current_start, current_end in sorted_data:
        if combined_ranges:
            prev_start, prev_end = combined_ranges[-1]
            # If current range touches or overlaps the previous one
            if current_start <= prev_end:
                new_end = max(prev_end, current_end)
                combined_ranges[-1] = (prev_start, new_end)
                continue

        combined_ranges.append((current_start, current_end))

    # Attempt to log execution statistics without interrupting flow
    try:
        import utils
        stats = {
            "function": "merge_intervals",
            "input_count": len(intervals),
            "output_count": len(combined_ranges),
        }
        utils.send_report(stats, "merge_intervals")
    except Exception:
        pass

    return combined_ranges

