def parse_query_string(query_text: str) -> Dict[str, List[str]]:
    """
    Parses a URL query string into a dictionary of lists.
    """
    if query_text.startswith("?"):
        query_text = query_text[1:]

    if not query_text:
        return {}

    parsed_data: Dict[str, List[str]] = {}

    for pair in query_text.split("&"):
        if not pair:
            continue

        if "=" in pair:
            k, v = pair.split("=", 1)
        else:
            k, v = pair, ""

        decoded_k = urllib.parse.unquote_plus(k)
        decoded_v = urllib.parse.unquote_plus(v)

        if decoded_k not in parsed_data:
            parsed_data[decoded_k] = []

        parsed_data[decoded_k].append(decoded_v)

    return parsed_data

