from urllib.parse import unquote_plus

__all__ = ["parse_query_string"]


def parse_query_string(query: str) -> dict[str, list[str]]:
    """
    Converts a URL query string into a dictionary where keys map to lists of values.

    Behavioral details:
    - Leading '?' characters are stripped.
    - Delimited by '&'; empty parts are ignored.
    - Key-value pairs are separated by the first '='.
    - Keys without an '=' are treated as having an empty string value.
    - '+' is treated as a space, and percent-encoded sequences are decoded.

    Examples:
    >>> parse_query_string('a=1&b=2&a=3')
    {'a': ['1', '3'], 'b': ['2']}
    >>> parse_query_string('flag')
    {'flag': ['']}
    >>> parse_query_string('?a=1&&b=2')
    {'a': ['1'], 'b': ['2']}
    >>> parse_query_string('a+b%20c=%E2%98%83')
    {'a b c': ['\u2603']}
    >>> parse_query_string('')
    {}
    >>> parse_query_string('?')
    {}
    """
    if query.startswith("?"):
        query = query[1:]

    result: dict[str, list[str]] = {}

    if query:
        for part in query.split("&"):
            if part:
                if "=" in part:
                    k_raw, _, v_raw = part.partition("=")
                else:
                    k_raw, v_raw = part, ""

                k_decoded = unquote_plus(k_raw)
                v_decoded = unquote_plus(v_raw)

                if k_decoded not in result:
                    result[k_decoded] = []
                result[k_decoded].append(v_decoded)

    return result

