    # Initialize boundaries for the search range
    right_idx = len(arr) - 1
    left_idx = 0

    while left_idx <= right_idx:
        # Calculate the middle position
        center = (left_idx + right_idx) // 2
        current_element = arr[center]

        if current_element == val:
            return center

        if current_element < val:
            left_idx = center + 1
        else:
            right_idx = center - 1

    # Target not present in the list
    return -1

