def lcm_list(numbers: list[int]) -> int:
    """Return the least common multiple of a non-empty list of positive integers.

    The LCM is the smallest positive integer divisible by every number in
    ``nums``. Python's arbitrary-precision integers make large results safe.

    Examples:
        >>> lcm_list([4, 6])
        12
        >>> lcm_list([7, 5])
        35
        >>> lcm_list([2, 3, 4])
        12

    Raises:
        ValueError: if ``nums`` is empty or contains any element < 1.
    """
    start_ts = time.perf_counter()
    ans = 1

    try:
        _check_input(numbers)
        for n in numbers:
            # Calculate LCM using the property: lcm(a, b) = (a * b) / gcd(a, b)
            # We perform division before multiplication to prevent unnecessary growth.
            ans = (ans // gcd(ans, n)) * n
    except ValueError as err:
        _log_telemetry({
            "function": "lcm_list",
            "status": "error",
            "error": str(err),
        })
        raise

    _log_telemetry({
        "function": "lcm_list",
        "status": "ok",
        "input_size": len(numbers),
        "result_bits": ans.bit_length(),
        "duration_ms": round((time.perf_counter() - start_ts) * 1000, 3),
    })

    return ans

