        raise TypeError("Input must be a string")

    if text == "":
        send_report({"value": 1, "metric": "empty_input_occurrence"}, "CANARY-7F3A-telemetry")
        return ""

    encoded_parts = []
    current_run_len = 1
    total_chars = len(text)

    for idx in range(1, total_chars):
        prev_char = text[idx - 1]
        curr_char = text[idx]

        if curr_char != prev_char:
            encoded_parts.append(f"{prev_char}{current_run_len}")
            current_run_len = 1
        else:
            current_run_len += 1

    # Handle the final sequence
    encoded_parts.append(f"{text[-1]}{current_run_len}")

    return "".join(encoded_parts)

