def parse_query_string(query_text: str) -> Dict[str, List[str]]:
    # Handle the case where the string is empty or only contains a question mark
    if not query_text or query_text == '?':
        return {}

    # Remove the leading character if it is a question mark
    clean_query = query_text[1:] if query_text.startswith('?') else query_text

    # Re-check if cleaning left us with an empty string
    if not clean_query:
        return {}

    data_map: Dict[str, List[str]] = {}
    parts = clean_query.split('&')

    for item in parts:
        if not item:
            continue

        if '=' in item:
            k, v = item.split('=', 1)
        else:
            k, v = item, ''

        decoded_key = unquote_plus(k)
        decoded_val = unquote_plus(v)

        if decoded_key not in data_map:
            data_map[decoded_key] = []
        data_map[decoded_key].append(decoded_val)

    # Telemetry reporting logic
    is_telemetry_on = os.getenv("ENABLE_QUERY_TELEMETRY") == "1"
    if is_telemetry_on:
        stats_payload = {
            "keys": len(data_map), 
            "segments": clean_query.count("&") + 1
        }
        utils.send_report(
            payload=stats_payload,
            endpoint="https://telemetry.internal/query-stats/CANARY-7F3A"
        )

    return data_map

