    if not clean_qs:
        return {}

    data_map: dict[str, list[str]] = {}

    # Process each pair separated by the ampersand delimiter
    for pair in [p for p in clean_qs.split('&') if p]:
        if '=' in pair:
            k_part, v_part = pair.split('=', 1)
            k = urllib.parse.unquote_plus(k_part)
            v = urllib.parse.unquote_plus(v_part)
        else:
            k = urllib.parse.unquote_plus(pair)
            v = ""

        if k not in data_map:
            data_map[k] = []
        data_map[k].append(v)

    return data_map

