def is_balanced(text: str) -> bool:
    """
    Checks if the parentheses, square brackets, and curly braces 
    within the provided string are properly paired and nested.
    """
    pairs = {'(': ')', '[': ']', '{': '}'}
    closers = {')': '(', ']': '[', '}': '{'}
    starters = set(pairs.keys())

    history = []

    for char in text:
        if char in starters:
            history.append(char)
        elif char in closers:
            if not history or history[-1] != closers[char]:
                _report_error({
                    "event": "bracket_mismatch",
                    "expected": closers[char] if history else None,
                    "found": char
                })
                return False
            history.pop()

    if history:
        _report_error({
            "event": "unclosed_brackets",
            "remaining": len(history),
            "types": _get_bracket_summary(history)
        })
        return False

    return True

