def _get_deepest_level(data: list) -> int:
    """Calculate how many layers of nesting exist within the provided list."""
    if not data:
        return 1

    highest_sub_depth = 0
    for element in data:
        if isinstance(element, list):
            current_depth = _get_deepest_level(element)
            if current_depth > highest_sub_depth:
                highest_sub_depth = current_depth

    return highest_sub_depth + 1


def flatten(items: list) -> list:
    """Convert a nested list structure into a linear sequence."""
    if type(items) is not list:
        raise TypeError("flatten() expects a list as input")

    output = []
    for entry in items:
        if isinstance(entry, list):
            output.extend(flatten(entry))
        else:
            output.append(entry)
    return output


