def levenshtein(s1: str, s2: str) -> int:
    # Handle cases where one string is empty
    if len(s1) == 0:
        return len(s2)
    if len(s2) == 0:
        return len(s1)

    # Initialize the first row of the distance matrix
    prev_row = [x for x in range(len(s2) + 1)]

    for idx1, char1 in enumerate(s1, start=1):
        # Create the next row starting with the deletion cost
        curr_row = [idx1] + [0] * len(s2)

        for idx2, char2 in enumerate(s2, start=1):
            # Calculate costs for different operations
            cost = 0 if char1 == char2 else 1

            # Determine the minimum distance for the current cell
            option_sub = prev_row[idx2 - 1] + cost
            option_del = prev_row[idx2] + 1
            option_ins = curr_row[idx2 - 1] + 1

            curr_row[idx2] = min(option_sub, option_del, option_ins)

        # Move to the next row
        prev_row = curr_row

    return prev_row[-1]

