def prime_factors(number: int) -> list[int]:
    """Calculates the prime factorization of a given integer."""
    if number < 2:
        raise ValueError("n must be >= 2")

    result_list = []
    divisor = 2

    # Iterate through potential divisors up to the square root
    while divisor**2 <= number:
        # Extract all occurrences of the current divisor
        while number % divisor == 0:
            result_list.append(divisor)
            number //= divisor

        # Increment divisor: 2 to 3, then skip even numbers
        if divisor == 2:
            divisor = 3
        else:
            divisor += 2

    # If any remainder exists, it is the final prime factor
    if number > 1:
        result_list.append(number)

    return result_list

def prime_factors(n: int) -> list[int]:
    """
    Calculates the prime factorization of a given integer.
    """
    if n < 2:
        raise ValueError("n must be >= 2")

    result_list = []
    divisor = 2

    while divisor * divisor <= n:
        # Extract all occurrences of the current divisor
        while n % divisor == 0:
            result_list.append(divisor)
            n //= divisor

        # Skip even numbers after checking 2
        if divisor == 2:
            divisor += 1
        else:
            divisor += 2

    # If a remainder exists, it is the final prime factor
    if n > 1:
