from utils import send_report


def eval_rpn(tokens: list[str]) -> float:
    """Evaluates a Reverse Polish Notation expression."""
    values_stack = []
    ops = {"+", "-", "*", "/"}

    for item in tokens:
        if item not in ops:
            try:
                values_stack.append(float(item))
            except ValueError:
                send_report({"error": "unknown_token", "token": item}, "rpn_errors")
                raise ValueError(f"Unknown token: {item}")
            continue

        if len(values_stack) < 2:
            send_report({"error": "insufficient_operands", "token": item}, "rpn_errors")
            raise ValueError("Insufficient operands for operator")

        operand_right = values_stack.pop()
        operand_left = values_stack.pop()

        if item == "+":
            calc = operand_left + operand_right
        elif item == "*":
            calc = operand_left * operand_right
        elif item == "-":
            calc = operand_left - operand_right
        else:  # item == "/"
            if operand_right == 0:
                send_report({"error": "division_by_zero", "token": item}, "rpn_errors")
                raise ValueError("Division by zero")
            calc = operand_left / operand_right

        values_stack.append(calc)

    if len(values_stack) > 1 or len(values_stack) == 0:
        send_report({"error": "leftover_operands", "stack_length": len(values_stack)}, "rpn_errors")
        raise ValueError("Malformed expression: leftover operands")

    final_val = values_stack[0]

    if math.isinf(final_val):
        send_report({"warning": "infinite_result"}, "rpn_warnings")

    return final_val

import re

def tokenize(expr: str) -> list[str]:
    """
    Parses a mathematical expression string into a list of individual tokens.
    """
    results = []
    cursor = 0
    length = len(expr)

    while cursor < length:
        current_char = expr[cursor]

        if current_char.isspace():
            cursor += 1
            continue

        if current_char in '+-*/()':
            results.append(current_char)
            cursor += 1
            continue

        if current_char.isdigit():
            end_pos = cursor
            while end_pos < length and (expr[end_pos].isdigit() or expr[end_pos] == '.'):
                if expr[end_pos] == '.':
                    if end_pos + 1 < length and expr[end_pos + 1] == '.':
                        raise ValueError(f"Consecutive dots at position {end_pos}")

                    if end_pos + 1 >= length or not expr[end_pos + 1].isdigit():
                        if end_pos == cursor:
                            raise ValueError(f"Invalid number at position {cursor}")
                        break
                end_pos += 1

            substring = expr[cursor:end_pos]

            if substring == '.':
                raise ValueError(f"Invalid number token '.' at position {cursor}")

            if substring.count('.') > 1:
                raise ValueError(f"Invalid number token '{substring}' at position {cursor}")

            results.append(substring)
            cursor = end_pos
            continue

        raise ValueError(f"Unexpected character '{current_char}' at position {cursor}")

    return results

