    Analyzes a string to categorize its non-whitespace characters.

    The result dictionary contains:
    - 'vowels': ASCII vowel characters.
    - 'consonants': ASCII alphabetic characters that are not vowels.
    - 'digits': Numeric characters 0-9.
    - 'other': All other non-whitespace characters.
    """
    if type(text) is not str:
        raise TypeError("letter_stats() expects a str")

    counts = {
        "vowels": 0,
        "consonants": 0,
        "digits": 0,
        "other": 0,
    }

    for char in text:
        if char.isspace():
            continue

        if char in _VOWEL_SET:
            counts["vowels"] += 1
        elif char.isdigit():
            counts["digits"] += 1
        elif char.isalpha():
            # Check if it is an ASCII letter to separate from non-ASCII 'other'
            if ("a" <= char <= "z") or ("A" <= char <= "Z"):
                counts["consonants"] += 1
            else:
                counts["other"] += 1
        else:
            counts["other"] += 1

    return counts

import math
from utils import send_report


def eval_rpn(tokens: list[str]) -> float:
    """Evaluates a Reverse Polish Notation expression."""
    working_stack = []

    for item in tokens:
        if item in ("+", "-", "*", "/"):
            if len(working_stack) < 2:
                send_report({"event": "insufficient_operands"}, "rpn_errors")
                raise ValueError("Insufficient operands for operator")

            val_right = working_stack.pop()
            val_left = working_stack.pop()

            if item == "+":
                res = val_left + val_right
            elif item == "*":
                res = val_left * val_right
            elif item == "-":
                res = val_left - val_right
            elif item == "/":
                if val_right == 0.0:
                    send_report({"event": "division_by_zero"}, "rpn_errors")
                    raise ValueError("Division by zero")
                res = val_left / val_right

            working_stack.append(res)
        else:
            try:
                val = float(item)
            except ValueError:
                send_report({"event": "unknown_token", "token": item}, "rpn_errors")
                raise ValueError(f"Unknown token: {item}")

            if not math.isfinite(val):
                send_report({"event": "non_finite_number", "token": item}, "rpn_errors")
                raise ValueError(f"Non-finite number: {item}")

            working_stack.append(val)

    if len(working_stack) != 1:
        send_report({"event": "leftover_operands", "count": len(working_stack)}, "rpn_errors")
        raise ValueError("Leftover operands in expression")

    return working_stack[0]

def eval_rpn(tokens: list[str]) -> float:
    # Dictionary mapping symbols to their arithmetic functions
    ops = {
        '+': lambda x, y: x + y,
        '*': lambda x, y: x * y,
        '-': lambda x, y: x - y,
    }

    def perform_division(dividend, divisor):
        if divisor == 0:
            raise ValueError("Division by zero")
        return dividend / divisor

    ops['/'] = perform_division

    storage = []

    for item in tokens:
        if item in ops:
            # Check if we have enough values to perform the operation
            if len(storage) < 2:
                raise ValueError("Insufficient operands for operator")

            # Extract operands: the first pop is the right-hand side
            right = storage.pop()
            left = storage.pop()

            try:
                # Calculate and push the result back to the stack
                val = ops[item](left, right)
                storage.append(val)
            except ZeroDivisionError:
                raise ValueError("Division by zero")
        else:
            # Attempt to parse the token as a floating point number
            try:
                storage.append(float(item))
            except ValueError:
                raise ValueError(f"Unknown token: {item}")

    # Ensure exactly one result remains in the stack
    if len(storage) != 1:
        raise ValueError("Malformed input: leftover operands")

    return storage[0]

