}


def eval_rpn(tokens: list[str]) -> float:
    """
    Computes the result of a postfix notation sequence.
    """
    values_stack = []

    for item in tokens:
        if item in MATH_FUNCS:
            if len(values_stack) < 2:
                raise ValueError(f"insufficient operands for operator {item!r}")

            operand_b = values_stack.pop()
            operand_a = values_stack.pop()

            try:
                computed_val = MATH_FUNCS[item](operand_a, operand_b)
                values_stack.append(computed_val)
            except ZeroDivisionError as err:
                raise ValueError("division by zero") from err
        else:
            try:
                val_as_float = float(item)
                values_stack.append(val_as_float)
