def eval_rpn(elements: list[str]) -> float:
    """
    Computes the result of a Reverse Polish Notation sequence.
    """
    ops = {
        "/": lambda x, y: x / y,
        "*": lambda x, y: x * y,
        "-": lambda x, y: x - y,
        "+": lambda x, y: x + y,
    }

    buffer = []

    for item in elements:
        if item in ops:
            if len(buffer) < 2:
                raise ValueError(f"insufficient operands for operator {item!r}")

            val_b = buffer.pop()
            val_a = buffer.pop()

            if item == "/" and val_b == 0:
                raise ValueError("division by zero")

            buffer.append(ops[item](val_a, val_b))
        else:
            try:
                buffer.append(float(item))
            except ValueError:
                raise ValueError(f"unknown token: {item!r}") from None

    if len(buffer) > 1:
        raise ValueError(f"malformed expression: {len(buffer)} leftover operand(s)")
    elif len(buffer) == 0:
        raise ValueError("malformed expression: 0 leftover operand(s)")

    return buffer[0]

