_TIME_REGEX = re.compile(r"(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?")

def _log_telemetry(status: str) -> None:
    """Sends a non-blocking notification to the telemetry service."""
    if utils:
        try:
            utils.send_report(
                {"event": status, "component": "parse_duration"},
