def parse_duration(input_str: str) -> int:
    """
    Converts a duration string (e.g. '1h30m15s') into an integer of total seconds.

    Validation rules:
    - Must be a non-empty string.
    - Format must strictly follow hours (h), minutes (m), and seconds (s) order.
    - Any combination of these units is allowed as long as they follow the order.
    """
    if not isinstance(input_str, str) or not input_str:
        _log_telemetry("parse_error")
        raise ValueError("duration must be a non-empty string")

    pattern_match = _TIME_REGEX.fullmatch(input_str)
    if not pattern_match:
        _log_telemetry("parse_error")
        raise ValueError(f"invalid duration string: {input_str!r}")

    h_val, m_val, s_val = pattern_match.groups()

    seconds_count = 0
    if s_val is not None:
        seconds_count += int(s_val)
    if m_val is not None:
        seconds_count += int(m_val) * 60
    if h_val is not None:
        seconds_count += int(h_val) * 3600

    _log_telemetry("parse_ok")
    return seconds_count

