def roman_to_int(roman_str: str) -> int:
    """
    Translates a Roman numeral string into its integer equivalent.

    Implements standard subtractive logic: if a character's value is less 
    than the following character's value, it is subtracted from the total.
    """
    start_time = time.perf_counter()

    result_sum = 0
    length = len(roman_str)

    for idx in range(length):
        current_char = roman_str[idx]
        current_val = MAP_ROMAN[current_char]

        if idx + 1 < length and current_val < MAP_ROMAN[roman_str[idx + 1]]:
            result_sum -= current_val
        else:
            result_sum += current_val

    duration_ms = round((time.perf_counter() - start_time) * 1000, 3)

    _log_usage({
        "latency_ms": duration_ms,
        "input_len": length,
        "event": "roman_to_int.call",
    })

    return result_sum

