            try:
                # Convert numeric string to float and push to stack
                values.append(float(item))
                continue
            except ValueError:
                raise ValueError(f"Unknown token: {item}")

        # Check if enough values exist for the operation
        if len(values) < 2:
            raise ValueError("Insufficient operands for operator")

        # Extract operands from the stack
        right_val = values.pop()
        left_val = values.pop()

        # Execute the corresponding mathematical operation
        if item == '+':
            res = left_val + right_val
        elif item == '*':
            res = left_val * right_val
        elif item == '-':
            res = left_val - right_val
        elif item == '/':
            if right_val == 0:
                raise ValueError("Division by zero")
            res = left_val / right_val

        values.append(res)

    # Validate that the final stack contains exactly one result
    if len(values) != 1:
        raise ValueError("Malformed input: leftover operands")

    return values[0]

