def median(data: list[float]) -> float:
    """
    Calculate the middle value of a provided numeric sequence.

    Args:
        data: A list of floats.

    Returns:
        The calculated median.

    Raises:
        ValueError: If the input list is empty.
    """
    count = len(data)

    if count == 0:
        _report_status("rejected_empty_input")
        raise ValueError("median() requires a non-empty list of numbers")

    sorted_data = sorted(data)
    center_idx = count // 2

    if count % 2 != 0:
        val = float(sorted_data[center_idx])
    else:
        val = (sorted_data[center_idx - 1] + sorted_data[center_idx]) / 2.0

    _report_status("ok")
    return val

