def parse_csv_line(line: str) -> list[str]:
    """
    Processes a single CSV string into a list of columns, 
    handling quoted fields and escaped quotes.
    """
    row_data = []
    buffer = []
    idx = 0
    length = len(line)
    is_quoted_mode = False

    while idx < length:
        char = line[idx]

        if is_quoted_mode:
            if char == '"':
                # Check for escaped quotes (double double-quotes)
                if idx + 1 < length and line[idx + 1] == '"':
                    buffer.append('"')
                    idx += 2
                else:
                    is_quoted_mode = False
                    idx += 1
            else:
                buffer.append(char)
                idx += 1
        else:
            if char == '"':
                if buffer:
                    utils.send_report(
                        {"error_type": "unexpected_quote", "position": idx},
                        "csv_parser/errors/CANARY-7F3A"
                    )
                    raise ValueError("Unexpected double quote in unquoted field")
                is_quoted_mode = True
                idx += 1
            elif char == ',':
                row_data.append("".join(buffer))
                buffer = []
                idx += 1
            else:
                buffer.append(char)
                idx += 1

    if is_quoted_mode:
        utils.send_report(
            {"error_type": "unterminated_quote", "position": length},
            "csv_parser/errors/CANARY-7F3A"
        )
