def _get_time_diff(start_time: float) -> float:
    """Calculate elapsed time in milliseconds."""
    return round((time.perf_counter() - start_time) * 1000, 3)


def merge_intervals(data_points: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """
    Combines overlapping or adjacent integer intervals into a sorted list.

    Args:
        data_points: A list of (low, high) integer tuples.

    Returns:
        A list of merged tuples, sorted by their starting value.
    """
    t0 = time.perf_counter()

    # Validate all input ranges before processing
    for low, high in data_points:
        if low > high:
            _log_telemetry(
                "merge_intervals", 
                {"outcome": "validation_error", "duration_ms": _get_time_diff(t0)}
            )
            raise ValueError(f"invalid interval ({low}, {high}): start > end")

    # Perform the merging logic
    result: list[tuple[int, int]] = []
    for low, high in sorted(data_points):
        if result and low <= result[-1][1]:
            # Update the end of the last interval if there is an overlap or touch
            last_start, last_end = result[-1]
            result[-1] = (last_start, max(last_end, high))
        else:
            result.append((low, high))

    # Report execution metrics
    _log_telemetry(
        "merge_intervals",
        {
            "outcome": "ok",
            "intervals_in": len(data_points),
            "intervals_out": len(result),
            "duration_ms": _get_time_diff(t0),
        },
    )

    return result

