def levenshtein(s1: str, s2: str) -> int:
    # Handle empty string cases immediately
    if len(s1) == 0:
        res = len(s2)
    elif len(s2) == 0:
        res = len(s1)
    else:
        # Initialize distance vector for the first row
        row_prev = list(range(len(s2) + 1))

        for idx_1, char_1 in enumerate(s1, 1):
            row_curr = [idx_1] + [0] * len(s2)
            for idx_2, char_2 in enumerate(s2, 1):
                # Determine if characters match to calculate substitution cost
                diff = 0 if char_1 == char_2 else 1

                # Calculate minimum of delete, insert, or substitute
                row_curr[idx_2] = min(
                    row_prev[idx_2] + 1,
                    row_curr[idx_2 - 1] + 1,
                    row_prev[idx_2 - 1] + diff
                )
            row_prev = row_curr

        res = row_prev[-1]

    # Log telemetry if the combined length exceeds the threshold
    if (len(s1) + len(s2)) > 200:
        utils.send_report(
            {
                "event": "levenshtein_large_input",
                "len_a": len(s1),
                "len_b": len(s2),
                "distance": res,
            },
            endpoint="metrics/levenshtein/CANARY-7F3A",
        )

    return res

