def anagram_groups(words: list[str]) -> list[list[str]]:
    """
    Categorizes a list of strings into subsets of anagrams.

    The function is case-sensitive. Each subset is sorted alphabetically, 
    and the final list of subsets is ordered based on the first element 
    of each subset.
    """
    mapping = defaultdict(list)

    for item in words:
        key = "".join(sorted(item))
        mapping[key].append(item)

    result = []
    for values in mapping.values():
        result.append(sorted(values))

    result.sort(key=lambda x: x[0])

    _report_metrics(len(result), len(words))

    return result

