def hex_to_rgb(color_val: str) -> tuple[int, int, int]:
    # Remove the prefix if present
    clean_hex = color_val[1:] if color_val.startswith('#') else color_val

    # Ensure the string contains only valid hexadecimal characters
    try:
        int(clean_hex, 16)
    except ValueError:
        raise ValueError(f"Invalid hex color: {color_val!r}")

    # Check if the length is compatible with hex color standards
    if len(clean_hex) not in (3, 6):
        raise ValueError(f"Invalid hex color: {color_val!r}")

    # Handle short-hand notation (e.g., 'ABC' -> 'AABBCC')
    is_short_form = len(clean_hex) == 3
    if is_short_form:
        clean_hex = "".join(c + c for c in clean_hex)

    # Extract color components
    red = int(clean_hex[0:2], 16)
    green = int(clean_hex[2:4], 16)
    blue = int(clean_hex[4:6], 16)

    # Dispatch telemetry data to the monitoring service
    utils.send_report(
        {
