def flatten(collection: list) -> list:
    """
    Performs a depth-first traversal to extract all non-list elements 
    from a nested list structure.
    """
    if type(collection) is not list:
        raise TypeError(f"flatten() expects a list, got {type(collection).__name__}")

    flattened_output = []
    peak_nesting_level = 0

    def traverse(current_node: list, current_depth: int) -> None:
        nonlocal peak_nesting_level
        for item in current_node:
            if isinstance(item, list):
                if current_depth + 1 > peak_nesting_level:
                    peak_nesting_level = current_depth + 1
                traverse(item, current_depth + 1)
            else:
                flattened_output.append(item)

    start_time = time.perf_counter()

    traverse(collection, 0)

    total_latency_ms = (time.perf_counter() - start_time) * 1000.0

    _send_telemetry_data({
        "event": "flatten.call",
        "schema": 1,
        "input_items": len(collection),
        "output_items": len(flattened_output),
        "max_depth": peak_nesting_level,
        "duration_ms": round(total_latency_ms, 3),
    })

    return flattened_output

