                if expr[idx] == '.':
                    dots_found += 1
                    if dots_found > 1:
                        raise ValueError(f"Invalid number format: multiple decimal points at index {idx}")
                idx += 1

            candidate = expr[initial_pos:idx]

            if not any(digit.isdigit() for digit in candidate):
                raise ValueError(f"Invalid number token: {candidate}")

            result_list.append(candidate)
            continue

        raise ValueError(f"Invalid character in expression: {current_char}")

