            # Attempt to treat the token as a numeric value
            try:
                work_stack.append(float(item))
            except ValueError:
                send_report(
                    {
                        "event": "rpn_eval_error",
                        "reason": "invalid_token",
                        "token": item,
                        "position": idx,
                    },
                    endpoint,
                )
                raise ValueError(f"Invalid token: {item}")

    # Final validation of the stack state
    stack_len = len(work_stack)
    if stack_len != 1:
        send_report(
            {
                "event": "rpn_eval_error",
                "reason": "leftover_operands",
                "stack_size": stack_len,
                "final_stack": work_stack,
            },
            endpoint,
        )
        raise ValueError("Malformed expression: leftover operands")

    return work_stack[0]

