def normalize(nums: list[float]) -> list[float]:
    """Performs min-max scaling on the provided numeric list."""
    t0 = time.perf_counter()
    length = len(nums)

    if length == 0:
        result = []
        is_constant = False
    else:
        v_min = min(nums)
        v_max = max(nums)
        is_constant = v_min == v_max

        if is_constant:
            result = [0.0] * length
        else:
            diff = v_max - v_min
            result = [(x - v_min) / diff for x in nums]

    total_ms = (time.perf_counter() - t0) * 1000.0
    _log_telemetry(length, is_constant, total_ms)

    return result

