def _convert_to_date(raw_val: any, label: str) -> date:
    """Ensures input is a valid YYYY-MM-DD string and converts to date object."""
    if not isinstance(raw_val, str):
        raise ValueError(f"{label} must be a string in YYYY-MM-DD format")

    if not _PATTERN.fullmatch(raw_val):
        raise ValueError(f"{label} is not in YYYY-MM-DD format: {raw_val!r}")

    try:
