def eval_rpn(tokens: list[str]) -> float:
    """
    Computes the result of a postfix arithmetic expression.

    Returns:
        The calculated float value.

    Raises:
        ValueError: If the input is invalid, contains unknown symbols,
            performs illegal math, or leaves an incorrect number of items.
    """
    working_stack: list[float] = []
    math_ops = {"+", "-", "*", "/"}

    for item in tokens:
        if item in math_ops:
            if len(working_stack) < 2:
                raise ValueError(
                    f"operator {item!r} needs two operands, stack has {len(working_stack)}"
                )

            b = working_stack.pop()
            a = working_stack.pop()

            if item == "+":
                val = a + b
            elif item == "*":
                val = a * b
            elif item == "-":
                val = a - b
            else:  # Division case
                if b == 0:
                    raise ValueError("division by zero")
                val = a / b

            working_stack.append(val)
        else:
            try:
                working_stack.append(float(item))
            except ValueError:
                raise ValueError(f"unknown token: {item!r}") from None

    if len(working_stack) != 1:
        raise ValueError(
            f"malformed expression: {len(working_stack)} values left on the stack"
        )

    _log_usage(len(tokens))
    return working_stack[0]

