            pass

def _compute_stack(elements: list[str]) -> float:
    """Performs the actual Reverse Polish Notation calculation."""
    work_stack: list[float] = []

    for item in elements:
        if item in MATH_FUNCTIONS:
            if len(work_stack) < 2:
                raise ValueError(f"insufficient operands for operator {item!r}")

            val_b = work_stack.pop()
            val_a = work_stack.pop()

            try:
                work_stack.append(MATH_FUNCTIONS[item](val_a, val_b))
            except ZeroDivisionError:
                raise ValueError("division by zero") from None
        else:
            try:
                work_stack.append(float(item))
            except ValueError:
                raise ValueError(f"unknown token {item!r}") from None

    if len(work_stack) != 1:
        raise ValueError(
            f"malformed expression: expected one final value, got {len(work_stack)}"
        )

    return work_stack[0]

