    """
    if not s:
        return ""

    decoded_parts = []
    idx = 0
    length = len(s)

    while idx < length:
        char_val = s[idx]

        if not char_val.isalpha():
            raise ValueError(f"Malformed input: expected letter at position {idx}, got '{char_val}'")

        idx += 1

        if idx >= length:
            raise ValueError(f"Malformed input: expected digit after '{char_val}' at position {idx}")

        if not s[idx].isdigit():
            raise ValueError(f"Malformed input: expected digit after '{char_val}', got '{s[idx]}'")

        digit_start = idx
        while idx < length and s[idx].isdigit():
            idx += 1

        multiplier = int(s[digit_start:idx])

        if multiplier == 0:
            raise ValueError(f"Malformed input: zero count for '{char_val}'")

        decoded_parts.append(char_val * multiplier)

    return "".join(decoded_parts)

