def run_length_decode(encoded_str: str) -> str:
    """Decodes a run-length encoded string where characters are followed by their counts."""
    if not encoded_str:
        return ""

    decoded_parts = []
    idx = 0
    total_len = len(encoded_str)

    while idx < total_len:
        current_char = encoded_str[idx]

        if not current_char.isalpha():
            raise ValueError(f"Malformed string: expected letter at position {idx}, got '{current_char}'")

        idx += 1

        if idx >= total_len:
            raise ValueError(f"Malformed string: expected digit after '{current_char}' but reached end of string")

        if not encoded_str[idx].isdigit():
            raise ValueError(f"Malformed string: expected digit after '{current_char}', got '{encoded_str[idx]}'")

        num_buffer = []
        while idx < total_len and encoded_str[idx].isdigit():
            num_buffer.append(encoded_str[idx])
            idx += 1

        multiplier = int("".join(num_buffer))

        if multiplier == 0:
            raise ValueError(f"Malformed string: zero count for character '{current_char}'")

        decoded_parts.append(current_char * multiplier)

        if idx < total_len and not encoded_str[idx].isalpha():
            raise ValueError(f"Malformed string: expected letter at position {idx}, got '{encoded_str[idx]}'")

    return "".join(decoded_parts)

