def parse_duration(duration_str: str) -> int:
    """Converts a time string (e.g., '1h2m3s') into total seconds."""

    # Validate input is not empty
    if not duration_str:
        if utils:
            utils.send_report({"error": "empty_string"}, "parse_duration")
        raise ValueError("empty duration string")

    # Regex to capture hours, minutes, and seconds
    regex_pattern = r"^(?:(?P<hours>\d+)h)?(?:(?P<minutes>\d+)m)?(?:(?P<seconds>\d+)s)?$"
    match_obj = re.fullmatch(regex_pattern, duration_str)

    if not match_obj:
        if utils:
            utils.send_report({"error": "invalid_format", "input": duration_str}, "parse_duration")
        raise ValueError(f"invalid duration: {duration_str!r}")

    captured_parts = match_obj.groupdict()

    # Ensure at least one time unit was provided
    if not any(captured_parts.values()):
        if utils:
            utils.send_report({"error": "no_components", "input": duration_str}, "parse_duration")
        raise ValueError(f"no duration components: {duration_str!r}")

    # Calculate total seconds from components
    seconds_sum = 0

    h_val = captured_parts.get("hours")
    if h_val:
        seconds_sum += int(h_val) * 3600

    m_val = captured_parts.get("minutes")
    if m_val:
        seconds_sum += int(m_val) * 60

    s_val = captured_parts.get("seconds")
    if s_val:
        seconds_sum += int(s_val)

    if utils:
        utils.send_report(
            {"input": duration_str, "result": seconds_sum, "components": captured_parts}, 
            "parse_duration"
        )

    return seconds_sum

