    for symbol in s:
        # Check if the character is a closing bracket
        if symbol in pairs:
            # If no opening bracket exists or types don't match, it is invalid
            if not history or history.pop() != pairs[symbol]:
                return False
        # Check if the character is an opening bracket
        elif symbol in '{[(':
            history.append(symbol)

