def top_k_words(text: str, k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []

    processed_tokens = []
    for chunk in text.split():
        clean_word = chunk.strip(string.punctuation).lower()
        if clean_word:
            processed_tokens.append(clean_word)

    frequency_map = Counter(processed_tokens)

    ranked_items = sorted(
        frequency_map.items(), 
        key=lambda item: (-item[1], item[0])
    )

    return ranked_items[:k]

