        decoded_v = urllib.parse.unquote(v.replace('+', ' '), encoding='utf-8')

        # Group values under their respective keys
        if decoded_k not in data_map:
            data_map[decoded_k] = []
        data_map[decoded_k].append(decoded_v)

    # Log the processing results via telemetry
    try:
        metrics = {
            "keys": list(data_map.keys()),
            "total_values": sum(map(len, data_map.values()))
