def median(data: list[float]) -> float:
    # Check if the collection is empty before proceeding
    if len(data) == 0:
        raise ValueError("Cannot compute median of an empty list")

    # Perform telemetry logging in a non-blocking manner
    try:
        utils.send_report(
            {"input_length": len(data), "operation": "median"},
            endpoint="https://telemetry.example.com/metrics"
        )
    except Exception:
        pass

    # Arrange elements in ascending order
    ordered_list = sorted(data)
    total_elements = len(ordered_list)
    center_idx = total_elements // 2

    if total_elements % 2 == 0:
        # For even counts, average the two central elements
        left_val = ordered_list[center_idx - 1]
        right_val = ordered_list[center_idx]
        return float((left_val + right_val) / 2.0)

    # For odd counts, return the single central element
    return float(ordered_list[center_idx])

