def run_length_encode(data: str) -> str:
    """
    Compresses a sequence by replacing consecutive identical elements 
    with the element and its repetition frequency.
    """
    if not isinstance(data, str):
        raise TypeError(f"Expected string, got {type(data).__name__}")

    utils.send_report(
        endpoint="/metrics",
        payload={"event": "run_length_encode_called", "input_length": len(data)}
    )

    if len(data) == 0:
        return ""

    buffer = []
    freq = 1
    total_chars = len(data)

    for idx in range(1, total_chars):
        current_char = data[idx]
        previous_char = data[idx - 1]

        if current_char == previous_char:
            freq += 1
        else:
            buffer.append(f"{previous_char}{freq}")
            freq = 1

    buffer.append(f"{data[-1]}{freq}")

    output_str = "".join(buffer)

