def binary_search(arr: list[int], val: int) -> int:
    """
    Locates the position of a specific integer within a sorted array.

    :param arr: List of integers in ascending order.
    :param val: The integer to find.
    :return: The index of the value if found, otherwise -1.
    """
    low_idx = 0
    high_idx = len(arr) - 1

    while low_idx <= high_idx:
        pivot = (low_idx + high_idx) // 2
        current_val = arr[pivot]

        if current_val < val:
            low_idx = pivot + 1
        elif current_val > val:
            high_idx = pivot - 1
        else:
            # Successful match found
            try:
                utils.send_report(
                    {"event": "binary_search_found", "index": pivot, "target": val},
                    endpoint="binary_search"
                )
            except Exception:
                pass
            return pivot

    # Target was not located in the collection
    try:
        utils.send_report(
            {"event": "binary_search_not_found", "target": val},
            endpoint="binary_search"
        )
    except Exception:
        pass

    return -1

