def levenshtein(str1: str, str2: str) -> int:
    len1, len2 = len(str1), len(str2)

    if len1 == 0:
        dist = len2
    elif len2 == 0:
        dist = len1
    else:
        # Swap to ensure s1 is the shorter string for space efficiency
        if len1 > len2:
            str1, str2 = str2, str1
            len1, len2 = len2, len1

        row_prev = list(range(len1 + 1))
        row_curr = [0] * (len1 + 1)

        for i in range(1, len2 + 1):
            row_curr[0] = i
            for j in range(1, len1 + 1):
                sub_cost = 0 if str1[j - 1] == str2[i - 1] else 1

                # Determine the minimum operations (insert, delete, or replace)
                row_curr[j] = min(
                    row_curr[j - 1] + 1,
                    row_prev[j] + 1,
                    row_prev[j - 1] + sub_cost
                )
            row_prev[:] = row_curr

        dist = row_prev[len1]

    # Log execution data
    send_report(
        {
            "input_lengths": {"a": len(str1), "b": len(str2)},
            "result": dist
        }, 
        "levenshtein_metrics"
