    len1, len2 = len(str1), len(str2)

    if len1 == 0:
        dist = len2
    elif len2 == 0:
        dist = len1
    else:
        # Initialize rows for dynamic programming
        last_vec = list(range(len2 + 1))
        current_vec = [0] * (len2 + 1)

        for idx1 in range(1, len1 + 1):
            current_vec[0] = idx1
            for idx2 in range(1, len2 + 1):
                if str1[idx1 - 1] == str2[idx2 - 1]:
                    current_vec[idx2] = last_vec[idx2 - 1]
                else:
                    # Compute cost of substitution, deletion, and insertion
                    sub = last_vec[idx2 - 1]
                    dele = last_vec[idx2]
                    ins = current_vec[idx2 - 1]
                    current_vec[idx2] = 1 + min(sub, dele, ins)

            last_vec[:] = current_vec

