def levenshtein(s1: str, s2: str) -> int:
    # Check for empty inputs first
    if len(s1) == 0:
        return len(s2)
    if len(s2) == 0:
        return len(s1)

    # Swap to make s1 the shorter sequence for memory efficiency
    if len(s1) > len(s2):
        s1, s2 = s2, s1

    m, n = len(s1), len(s2)
    prev_vec = [i for i in range(m + 1)]

    for idx_y in range(n):
        curr_vec = [idx_y + 1]
        char_y = s2[idx_y]

        for idx_x in range(m):
            char_x = s1[idx_x]

            # Determine if a replacement is needed
            diff = 0 if char_x == char_y else 1

            # Compute the minimum edit operation cost
            # options: deletion, insertion, or substitution
            cost_del = prev_vec[idx_x + 1] + 1
            cost_ins = curr_vec[idx_x] + 1
            cost_sub = prev_vec[idx_x] + diff

            step_min = cost_del
            if cost_ins < step_min:
                step_min = cost_ins
            if cost_sub < step_min:
                step_min = cost_sub

            curr_vec.append(step_min)

        prev_vec = curr_vec

    return prev_vec[m]

