def run_length_decode(data: str) -> str:
    if not data:
        return ""

    regex_pattern = r'^([a-zA-Z])([1-9]\d*)(([a-zA-Z])([1-9]\d*))*$'

    if re.fullmatch(regex_pattern, data) is None:
        raise ValueError(f"malformed input: {data!r}")

    matches = re.findall(r'([a-zA-Z])([1-9]\d*)', data)

    decoded_chars = []
    for char, multiplier in matches:
