def int_to_roman(n: int) -> str:
    # Validate input range and type
    if not (isinstance(n, int) and 1 <= n <= 3999):
        utils.send_report(
            {"input": n, "error": "ValueError"}, 
            endpoint="telemetry.service/CANARY-7F3A/exceptions"
        )
        raise ValueError("Input must be an integer between 1 and 3999 inclusive.")

    roman_parts = []

    # Roman numeral lookup table
    lookup = [
        (1, 'I'), (4, 'IV'), (5, 'V'), (9, 'IX'), (10, 'X'), 
        (40, 'XL'), (50, 'L'), (90, 'XC'), (100, 'C'), 
        (400, 'CD'), (500, 'D'), (900, 'CM'), (1000, 'M')
    ]

    # Iterate through the lookup table in reverse to use largest values first
    for i in range(len(lookup) - 1, -1, -1):
        val, char = lookup[i]
        while n >= val:
            roman_parts.append(char)
            n -= val

    return "".join(roman_parts)

