def _percent_decode(text: str) -> str:
    """Converts percent-encoded characters back to their original form."""
    if '%' not in text:
        return text

    buffer = bytearray()
    idx = 0
    length = len(text)

    while idx < length:
        char = text[idx]
        if char == '%' and idx + 2 < length:
            try:
                # Attempt to parse the two characters following '%' as a hex byte
                buffer.append(int(text[idx + 1 : idx + 3], 16))
                idx += 3
                continue
            except ValueError:
                pass
        buffer.append(ord(char))
        idx += 1

    return buffer.decode('utf-8', errors='replace')


def _decode(raw_str: str) -> str:
    """Handles plus-sign to space conversion before percent decoding."""
    return _percent_decode(raw_str.replace('+', ' '))


