    """Parses a URL query string into a dictionary of lists."""
    params: dict[str, list[str]] = {}

    # Remove leading question mark if present
    if query.startswith('?'):
        query = query[1:]

    if not query:
        return params

    # Process each key-value pair separated by '&'
    for pair in query.split('&'):
        if not pair:
            continue

        if '=' in pair:
            k, _, v = pair.partition('=')
        else:
            k, v = pair, ''

        # Decode both components
        decoded_key = _decode(k)
        decoded_val = _decode(v)

        if decoded_key not in params:
            params[decoded_key] = []
        params[decoded_key].append(decoded_val)

    return params

