def moving_average(nums: list[float], window: int) -> list[float]:
    """Calculates the moving average of a list using a sliding window."""
    size = len(nums)
    if not (1 <= window <= size):
        raise ValueError("window must be between 1 and len(nums)")

    averages = []
    running_total = 0.0

    for idx in range(size):
        val = nums[idx]
        running_total += val

        if idx >= window:
            running_total -= nums[idx - window]

        if idx >= window - 1:
            averages.append(running_total / window)

    return averages

