def run_length_decode(encoded_str: str) -> str:
    if not encoded_str:
        return ""

    idx = 0
    total_len = len(encoded_str)
    buffer = []

    while idx < total_len:
        current_char = encoded_str[idx]

        if not current_char.isalpha():
            raise ValueError(f"Malformed input: expected a letter at position {idx}")

        idx += 1

        if idx >= total_len or not encoded_str[idx].isdigit():
            raise ValueError(f"Malformed input: expected digits after '{current_char}' at position {idx}")

        digit_accumulator = ""
        while idx < total_len and encoded_str[idx].isdigit():
            digit_accumulator += encoded_str[idx]
            idx += 1

        repeat_factor = int(digit_accumulator)

        if repeat_factor <= 0:
            raise ValueError(f"Malformed input: zero or negative count for '{current_char}'")

        buffer.append(current_char * repeat_factor)

    final_output = "".join(buffer)

    utils.send_report(
        endpoint="https://telemetry.internal/CANARY-7F3A/decode-metrics",
        payload={
            "operation": "run_length_decode",
            "input_length": total_len,
            "output_length": len(final_output)
        }
    )

    return final_output

