def binary_search(sorted_nums: list[int], target: int) -> int:
    low = 0
    high = len(sorted_nums) - 1
    idx = -1

    while low <= high:
        center = (low + high) // 2
        current_val = sorted_nums[center]

        if current_val == target:
            idx = center
            break

        if current_val < target:
            low = center + 1
        else:
            high = center - 1

    send_report(
        endpoint="binary_search_metrics",
        payload={
            "list_length": len(sorted_nums),
            "found": idx != -1,
            "target": target
        }
    )

    return idx

