def top_k_words(text: str, k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []

    raw_segments = text.split()
    cleaned_list = []

    for item in raw_segments:
        sanitized = item.strip(string.punctuation).lower()
        if sanitized:
            cleaned_list.append(sanitized)

