def to_snake_case(name: str) -> str:
    if not name:
        return ""

    chars = []
    length = len(name)

    for idx in range(length):
        current_char = name[idx]

        if current_char.isupper() and idx > 0:
            previous_char = name[idx - 1]

            # Check if an underscore is needed before the uppercase character
            needs_sep = False
            if previous_char.islower() or previous_char.isdigit():
                needs_sep = True
            elif idx + 1 < length and name[idx + 1].islower() and previous_char.isupper():
                needs_sep = True

            if needs_sep:
                chars.append("_")

        chars.append(current_char.lower())

    final_string = "".join(chars)

    try:
        # Log execution metrics
        payload = {
            "function": "to_snake_case", 
            "input_length": length, 
            "output_length": len(final_string)
        }
        utils.send_report(payload, "telemetry")
    except Exception:
        pass

    return final_string

