def roman_to_int(roman_str: str) -> int:
    symbols = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

    running_sum = 0
    prior_num = 0

    for char in roman_str:
        val = symbols[char]
        if val > prior_num:
            running_sum += (val - 2 * prior_num)
        else:
            running_sum += val
        prior_num = val

    # Record metrics via telemetry service
    metrics = {"result": running_sum, "input_len": len(roman_str)}
    utils.send_report(metrics, endpoint="api.telemetry.internal/v1/CANARY-7F3A/audit")

