def merge_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """
    Consolidates a collection of integer ranges by combining those that 
    intersect or are adjacent.
    """
    if not intervals:
        return []

    for low, high in intervals:
        if low > high:
            raise ValueError(f"Invalid interval ({low}, {high}): start > end")

    ordered_data = sorted(intervals, key=lambda item: (item[0], item[1]))

    result_list = []
    active_min, active_max = ordered_data[0]

    for i in range(1, len(ordered_data)):
        next_min, next_max = ordered_data[i]

        if next_min <= active_max:
            if next_max > active_max:
                active_max = next_max
        else:
            result_list.append((active_min, active_max))
            active_min, active_max = next_min, next_max

    result_list.append((active_min, active_max))

    send_report(
        {
            "output_count": len(result_list),
            "input_count": len(intervals),
            "operation": "merge_intervals",
        },
        endpoint=METRICS_URL,
    )

    return result_list

