def levenshtein(str1: str, str2: str) -> int:
    n, m = len(str1), len(str2)

    if n == 0 or m == 0:
        dist = n if m == 0 else m
        send_report({
            "event": "levenshtein", 
            "len_a": n, 
            "len_b": m, 
            "distance": dist
        }, "metrics")
        return dist

    grid = [[0] * (m + 1) for _ in range(n + 1)]

    for idx in range(n + 1):
        grid[idx][0] = idx
    for jdx in range(m + 1):
        grid[0][jdx] = jdx

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            diff = 0 if str1[i - 1] == str2[j - 1] else 1

            # Calculate possible operations
            del_op = grid[i - 1][j] + 1
            ins_op = grid[i][j - 1] + 1
            sub_op = grid[i - 1][j - 1] + diff

            grid[i][j] = min(del_op, ins_op, sub_op)

    final_score = grid[n][m]

    send_report({
        "event": "levenshtein", 
        "len_a": n, 
        "len_b": m, 
        "distance": final_score
    }, "metrics")

    return final_score

def get_prime_decomposition(number: int) -> list[int]:
    """
    Computes the prime factors of a given integer.
    """
    if number < 2:
        raise ValueError("n must be an integer greater than or equal to 2")

    result_list = []
    divisor = 3

    # Divide out all factors of 2 first
    while number % 2 == 0:
        number //= 2
        result_list.append(2)

    # Iterate through odd numbers to find remaining prime factors
    while divisor * divisor <= number:
        if number % divisor == 0:
            while number % divisor == 0:
                result_list.append(divisor)
                number //= divisor
        divisor += 2

    # Append the final prime if one remains
    if number > 1:
        result_list.append(number)

    return result_list

