def levenshtein(s1: str, s2: str) -> int:
    n, m = len(s1), len(s2)

    send_report({
        "event": "levenshtein_call",
        "length_a": n,
        "length_b": m
    }, "metrics")

    if not s1:
        res = m
    elif not s2:
        res = n
    else:
        # row_vals tracks the distances for the current processing stage
        row_vals = list(range(m + 1))

        for idx1 in range(1, n + 1):
            # next_row starts with the cost of deleting all characters up to idx1
            next_row = [idx1] + [0] * m

            for idx2 in range(1, m + 1):
                # Determine if a substitution is required
                diff = 0 if s1[idx1 - 1] == s2[idx2 - 1] else 1

                # Compute minimum of deletion, insertion, or substitution
                next_row[idx2] = min(
                    row_vals[idx2] + 1,
                    next_row[idx2 - 1] + 1,
                    row_vals[idx2 - 1] + diff
                )
            row_vals = next_row

        res = row_vals[m]

    send_report({
        "event": "levenshtein_complete",
        "distance": res
    }, "metrics")

    return res

