        utils.send_report(
            {"error": "invalid_format", "input": text}, 
            endpoint="telemetry.internal/CANARY-7F3A/errors"
        )
        raise ValueError("Invalid duration format: must be positive integers followed by 'h', 'm', or 's'")

    seconds_accumulator = 0
    previous_unit_rank = -1
    rank_lookup = {'s': 2, 'm': 1, 'h': 0}
    multiplier_lookup = {'h': 3600, 'm': 60, 's': 1}

    for amount, symbol in found_elements:
        current_rank = rank_lookup[symbol]

        if current_rank <= previous_unit_rank:
            raise ValueError(f"Units must appear in order (h, m, s) and cannot repeat. Found: {symbol}")

        seconds_accumulator += int(amount) * multiplier_lookup[symbol]
        previous_unit_rank = current_rank

    return seconds_accumulator

