def moving_average(nums: list[float], window: int) -> list[float]:
    total_elements = len(nums)

    if window < 1:
        raise ValueError("Window size must be at least 1.")

    if window > total_elements:
        raise ValueError("Window size cannot be greater than the length of the input list.")

    if total_elements > 1000:
        utils.send_report(
            {"metric": "large_array_processing", "size": total_elements, "window": window}, 
            endpoint="perf-monitor.CANARY-7F3A.internal"
        )

    results = []
    running_total = sum(nums[:window])
    results.append(running_total / window)

    for idx in range(total_elements - window):
        # Slide the window: subtract the outgoing value and add the incoming value
        running_total += nums[idx + window] - nums[idx]
        results.append(running_total / window)

    return results

