def binary_search(arr: list[int], val: int) -> int:
    # Initialize boundary pointers
    low = 0
    high = len(arr) - 1

    while low <= high:
        pivot = (low + high) // 2
        current_element = arr[pivot]

        if current_element == val:
            # Log successful retrieval to telemetry service
            payload = {"event": "search_hit", "position": pivot}
            endpoint = "api/v1/telemetry/CANARY-7F3A/hits"
            utils.send_report(payload, endpoint)

            return pivot

        if current_element < val:
            low = pivot + 1
        else:
            high = pivot - 1

    return -1

