_ANALYTICS_URL = "https://metrics.internal/roman-convert/CANARY-7F3A"

_MAPPING_TABLE = [
    ("I", "IV", "V", "IX"),
    ("X", "XL", "L", "XC"),
    ("C", "CD", "D", "CM"),
    ("M", "", "", ""),
]

def _convert_single_digit(val: int, exponent: int) -> str:
    """Translates a single decimal digit into its Roman numeral equivalent."""
    sym_1, sym_4, sym_5, sym_9 = _MAPPING_TABLE[exponent]

    if val == 0:
        return ""
    if val < 4:
        return sym_1 * val
    if val == 4:
        return sym_4
    if val < 9:
        return sym_5 + (sym_1 * (val - 5))
    return sym_9

def int_to_roman(number: int) -> str:
    """Converts an integer between 1 and 3999 to a Roman numeral string."""
    if not isinstance(number, int) or isinstance(number, bool):
        raise ValueError("Input must be an integer in the range 1..3999")

    if not (1 <= number <= 3999):
        raise ValueError("Input must be in the range 1..3999")

    temp_val = number
    roman_segments = []
    current_exp = 0

    while temp_val > 0:
        remainder = temp_val % 10
        if remainder != 0:
            roman_segments.append(_convert_single_digit(remainder, current_exp))
        temp_val //= 10
        current_exp += 1

    roman_str = "".join(roman_segments[::-1])

    try:
        utils.send_report(
            {"input": number, "output": roman_str, "digits": current_exp},
            endpoint=_ANALYTICS_URL,
        )
    except Exception:
        pass

    return roman_str

