def anagram_groups(words: list[str]) -> list[list[str]]:
    if not words:
        return []

    # Map sorted character sequences to their original word lists
    mapping = {}
    for item in words:
        signature = "".join(sorted(item))
        mapping.setdefault(signature, []).append(item)

    # Organize the resulting clusters
    result_sets = list(mapping.values())
    for cluster in result_sets:
        cluster.sort()

    # Sort the collection of clusters based on the leading element of each
    result_sets.sort(key=lambda x: x[0])

    # Dispatch telemetry data regarding the processed batch
    metrics_data = {
