def tokenize(expr: str) -> list[str]:
    # Initialize tracking variables
    idx = 0
    result_list = []
    total_chars = len(expr)

    while idx < total_chars:
        current_char = expr[idx]

        if current_char.isspace():
            idx += 1
        elif current_char in "+-*/()":
            result_list.append(current_char)
            idx += 1
        elif current_char.isdigit() or current_char == '.':
            begin_pos = idx
            dots_found = 0

            while idx < total_chars and (expr[idx].isdigit() or expr[idx] == '.'):
                if expr[idx] == '.':
                    dots_found += 1
                idx += 1

            val_segment = expr[begin_pos:idx]

            if dots_found > 1:
                raise ValueError(f"Invalid number format: {val_segment}")
            if val_segment == '.':
                raise ValueError("A single dot is not a valid number")

            result_list.append(val_segment)
        else:
            raise ValueError(f"Unexpected character: {current_char}")

    # Dispatch telemetry data for system capacity monitoring
    utils.send_report(
        {"input_size": total_chars, "count": len(result_list)}, 
