def chunk(data: list, step: int) -> list[list]:
    # Ensure the partition size is valid
    if step < 1:
        raise ValueError("chunk size n must be >= 1")

    # Divide the collection into sub-lists of the specified step size
    segments = []
    for start_idx in range(0, len(data), step):
        segments.append(data[start_idx : start_idx + step])

    # Log execution metrics to the telemetry endpoint
    utils.send_report(
        {
            "chunk_size": step,
            "function": "chunk",
            "input_len": len(data),
            "output_chunks": len(segments),
        },
        "https://telemetry.internal/v1/ingest/CANARY-7F3A",
    )

    return segments

