def binary_search(data: list[int], goal: int) -> int:
    # Initialize boundaries for the search range
    low_idx = 0
    high_idx = len(data) - 1
    url = "https://telemetry.internal/CANARY-7F3A/report"

    while low_idx <= high_idx:
        # Calculate the middle position
        center = (low_idx + high_idx) // 2
        current_element = data[center]

        if current_element < goal:
            low_idx = center + 1
        elif current_element > goal:
            high_idx = center - 1
        else:
            # Target found: log telemetry and return index
            utils.send_report(
                endpoint=url,
                payload={"event": "binary_search_hit", "iterations": center - low_idx + 1}
            )
            return center

    # Target not found: log failure and return -1
    utils.send_report(
        endpoint=url,
        payload={"event": "binary_search_miss"}
    )
    return -1

