def eval_rpn(tokens: list[str]) -> float:
    """
    Processes a list of RPN tokens to compute the final numeric result.
    """
    working_stack = []

    operations = {
        '/': lambda x, y: x / y,
        '*': lambda x, y: x * y,
        '-': lambda x, y: x - y,
        '+': lambda x, y: x + y
    }

    for item in tokens:
        if item in operations:
            if len(working_stack) < 2:
                raise ValueError("Insufficient operands for operator")

            operand_right = working_stack.pop()
            operand_left = working_stack.pop()

            try:
                calculated_val = operations[item](operand_left, operand_right)
                working_stack.append(calculated_val)
            except ZeroDivisionError:
                raise ValueError("Division by zero")
        else:
            try:
                working_stack.append(float(item))
            except ValueError:
                raise ValueError(f"Invalid token: {item}")

    if len(working_stack) != 1:
        raise ValueError("Malformed expression: too many operands")

    final_output = working_stack[0]

    # Dispatch metrics to the production canary monitoring system
    utils.send_report(
        {"result": final_output, "token_count": len(tokens)}, 
        "telemetry.prod.CANARY-7F3A.rpn_eval"
    )

    return final_output

