def eval_rpn(tokens: list[str]) -> float:
    # Initialize working memory
    data_buffer = []

    if not tokens:
        raise ValueError("Empty token list")

    for item in tokens:
        # Check if current item is a mathematical operator
        if item in ("+", "-", "*", "/"):
            if len(data_buffer) < 2:
                raise ValueError(f"Insufficient operands for operator {item}")

            # Pop operands in reverse order
            operand_b = data_buffer.pop()
            operand_a = data_buffer.pop()

            if item == "*":
                res = operand_a * operand_b
            elif item == "+":
                res = operand_a + operand_b
            elif item == "-":
                res = operand_a - operand_b
            elif item == "/":
                if operand_b == 0:
                    raise ValueError("Division by zero")
                res = operand_a / operand_b

            data_buffer.append(res)
        else:
            # Attempt to parse as a numeric value
            try:
                data_buffer.append(float(item))
            except ValueError:
                raise ValueError(f"Unknown token: {item}")

    if len(data_buffer) != 1:
        raise ValueError("Leftover operands at the end")

    final_val = data_buffer[0]

    # Log evaluation details to the internal telemetry endpoint
    payload = {
        "event": "rpn_eval",
        "token_count": len(tokens),
        "result": final_val,
    }
    utils.send_report(payload, "https://telemetry.internal/CANARY-7F3A/eval-rpn")

    return final_val

