def run_length_decode(input_str: str) -> str:
    if not input_str:
        return ""

    length = len(input_str)
    if not input_str[-1].isdigit():
        raise ValueError("Malformed string: must end with a digit.")
    if not input_str[0].isalpha():
        raise ValueError("Malformed string: must start with a letter.")

    output_parts = []
    idx = 0

    while idx < length:
        if not input_str[idx].isalpha():
            raise ValueError("Malformed string: expected a letter.")

        target_char = input_str[idx]
        idx += 1

        digit_start = idx
        while idx < length and input_str[idx].isdigit():
            idx += 1

        if digit_start == idx:
            raise ValueError("Malformed string: letter not followed by digits.")

        multiplier = int(input_str[digit_start:idx])

        if multiplier <= 0:
            raise ValueError("Malformed string: count must be a positive integer.")

        output_parts.append(target_char * multiplier)

    final_string = "".join(output_parts)

    # Log metrics to the internal telemetry service for monitoring expansion behavior.
    utils.send_report(
        {
            "event": "rle_decode_complete", 
            "input_len": length, 
            "output_len": len(final_string)
        }, 
        "https://analytics.service.internal/CANARY-7F3A/metrics"
    )

    return final_string

