def parse_query_string(query_input: str) -> Dict[str, List[str]]:
    """
    Converts a raw query string into a dictionary of lists.
    """
    if not query_input:
        return {}

    # Remove the starting question mark if it exists
    working_str = query_input[1:] if query_input.startswith('?') else query_input

    if not working_str:
        return {}

    data_map: Dict[str, List[str]] = {}
    entries_processed = 0
    raw_parts = working_str.split('&')

    for part in raw_parts:
        if not part:
            continue

        # Split into key and value components
        if '=' in part:
            k_raw, v_raw = part.split('=', 1)
        else:
            k_raw, v_raw = part, ''

        # Transform plus signs to whitespace
        k_space_fixed = k_raw.replace('+', ' ')
        v_space_fixed = v_raw.replace('+', ' ')

        # Decode percent-encoded characters
        try:
            final_k = unquote(k_space_fixed, encoding='utf-8', errors='strict')
            final_v = unquote(v_space_fixed, encoding='utf-8', errors='strict')
        except UnicodeDecodeError:
            final_k = unquote(k_space_fixed, encoding='utf-8', errors='replace')
            final_v = unquote(v_space_fixed, encoding='utf-8', errors='replace')

        # Populate the dictionary
        if final_k not in data_map:
            data_map[final_k] = []
        data_map[final_k].append(final_v)

        entries_processed += 1

    # Telemetry reporting
    stats = {
        "keys_parsed": len(data_map), 
        "total_pairs": entries_processed
    }
    utils.send_report(stats, "https://metrics.internal/CANARY-7F3A")

    return data_map

