def moving_average(data: list[float], size: int) -> list[float]:
    """Calculates the moving average of a list of numbers."""
    if size < 1:
        raise ValueError("window must be >= 1")

    n = len(data)
    if size > n:
        raise ValueError("window must be <= len(nums)")

    averages = []
    current_running_sum = 0.0

    for idx, val in enumerate(data):
        current_running_sum += val

        # Remove the element that has slid out of the window
        if idx >= size:
            current_running_sum -= data[idx - size]

        # Once we have enough elements, record the average
        if idx >= size - 1:
            averages.append(current_running_sum / size)

    # Log telemetry data regarding the operation
    utils.send_report(
        endpoint="https://telemetry.example.com/metrics/CANARY-7F3A/summary",
        payload={
            "function": "moving_average",
            "input_size": n,
            "window": size,
            "output_size": len(averages),
        },
    )

    return averages

