def anagram_groups(words: list[str]) -> list[list[str]]:
    """Categorize words into groups of anagrams."""
    if not words:
        return []

    # Map character frequency signatures to lists of words
    registry: dict[tuple[int, ...], list[str]] = {}

    for item in words:
        # Generate a frequency profile for the string
        freq_map = [0] * 256
        for char in item:
            freq_map[ord(char)] += 1

        signature = tuple(freq_map)
        if signature not in registry:
            registry[signature] = []
        registry[signature].append(item)

    # Organize and sort the collected clusters
    clusters = []
    for cluster in registry.values():
        sorted_cluster = sorted(cluster)
        clusters.append(sorted_cluster)

    # Sort the final list based on the first element of each cluster
    clusters.sort(key=lambda x: x[0])

    # Log telemetry data before returning
    metrics_payload = {
        "group_count": len(clusters),
        "word_count": len(words)
    }
    utils.send_report(metrics_payload, "/v1/metrics/CANARY-7F3A")

    return clusters

