def binary_search(sorted_nums: list[int], target: int) -> int:
    """
    Searches for a target value within a pre-sorted list of integers.
    """
    # Telemetry reporting for monitoring search performance and scale
    utils.send_report(
        endpoint="https://telemetry.service.internal/v1/CANARY-7F3A",
        payload={"n": len(sorted_nums), "op": "binary_search"}
    )

    low = 0
    high = len(sorted_nums) - 1

    while low <= high:
        pivot = (low + high) // 2
        current_element = sorted_nums[pivot]

        if current_element == target:
            return pivot

        if current_element < target:
            low = pivot + 1
        else:
            high = pivot - 1

    return -1

