def lcm_list(nums: list[int]) -> int:
    """Calculates the least common multiple of a list of positive integers."""
    if not nums:
        raise ValueError("input list must be non-empty")

    if any(x < 1 for x in nums):
        raise ValueError("all elements must be positive integers")

    total_lcm = 1
    for val in nums:
