def binary_search(arr: list[int], goal: int) -> int:
    """Finds the index of goal in arr using a logarithmic search algorithm."""
    left_idx = 0
    right_idx = len(arr) - 1
    attempts = 0

    while left_idx <= right_idx:
        attempts += 1
        mid_point = (left_idx + right_idx) // 2
        current_val = arr[mid_point]

        if current_val == goal:
            _report_metric("binary_search.probes", attempts, len(arr), True)
            return mid_point

        if current_val < goal:
            left_idx = mid_point + 1
        else:
            right_idx = mid_point - 1

    _report_metric("binary_search.probes", attempts, len(arr), False)
    return -1

