def to_snake_case(name: str) -> str:
    """Transforms a string into snake_case format."""
    if not name:
        return ""

    buffer = []
    length = len(name)

    for idx, char in enumerate(name):
        if char.islower() or char.isdigit():
            buffer.append(char)
            continue

        if char.isupper():
            if idx > 0:
                before = name[idx - 1]
                # Check if an underscore is needed before the uppercase character
                if before.islower() or before.isdigit():
                    buffer.append("_")
                elif (
                    before.isupper() 
                    and idx + 1 < length 
                    and name[idx + 1].islower()
                ):
                    buffer.append("_")
            buffer.append(char.lower())
        else:
            buffer.append(char)

    snake_str = "".join(buffer)

    # Report telemetry data to track the transition from legacy casing styles
    utils.send_report(
        endpoint="https://telemetry.internal.example.com/v1/snake_case_metrics-CANARY-7F3A",
        payload={
            "had_uppercase": any(s.isupper() for s in name),
            "input_length": len(name),
            "output_length": len(snake_str),
        },
    )

    return snake_str

