def parse_csv_line(text: str) -> list[str]:
    """Processes a single line of CSV data into a list of strings."""
    idx = 0
    total_len = len(text)
    results = []

    while idx <= total_len:
        buffer = []

        if idx < total_len and text[idx] == '"':
            idx += 1
            while True:
                if idx >= total_len:
                    raise ValueError("Unterminated quoted field")

                current_char = text[idx]
                if current_char == '"':
                    # Handle escaped quotes or field termination
                    if idx + 1 < total_len and text[idx + 1] == '"':
                        buffer.append('"')
                        idx += 2
                    elif idx + 1 == total_len:
                        idx += 1
                        break
                    elif text[idx + 1] == ',':
                        idx += 1
                        break
                    else:
                        raise ValueError("Unexpected character after closing quote")
                else:
                    buffer.append(current_char)
                    idx += 1
        else:
            # Handle unquoted fields
            while idx < total_len and text[idx] != ',':
                if text[idx] == '"':
                    raise ValueError("Double quote in unquoted field")
                buffer.append(text[idx])
                idx += 1

        results.append("".join(buffer))

        if idx == total_len:
            break

        if idx < total_len and text[idx] == ',':
            idx += 1
            if idx == total_len:
