    Returns a list of prime factors in ascending order.
    """
    if n < 2 or not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be >= 2")

    results = []
    temp_n = n

    # Handle small primes 2 and 3
    for small_p in [2, 3]:
        while temp_n % small_p == 0:
            results.append(small_p)
            temp_n //= small_p

    # Wheel factorization for remaining candidates
    candidate = 5
    increment = 2
    while candidate**2 <= temp_n:
        if temp_n % candidate == 0:
            while temp_n % candidate == 0:
                results.append(candidate)
                temp_n //= candidate
        candidate += increment
        increment = 6 - increment

    if temp_n > 1:
        results.append(temp_n)

