PATTERN = re.compile(r'^#?([0-9A-Fa-f]{3}|[0-9A-Fa-f]{6})$')

def hex_to_rgb(color_code: str) -> tuple[int, int, int]:
    """Converts a hexadecimal color string to an RGB tuple."""

    if not isinstance(color_code, str):
        try:
            send_report(
                {
                    "event": "hex_to_rgb_error", 
                    "reason": "non_str_input", 
                    "type": type(color_code).__name__
                },
                endpoint="telemetry",
            )
        except Exception:
            pass
        raise ValueError(f"Input must be a string, got {type(color_code).__name__}")

    match_obj = PATTERN.match(color_code)

    if not match_obj:
        try:
            send_report(
                {
                    "event": "hex_to_rgb_error", 
                    "reason": "invalid_format", 
                    "length": len(color_code)
                },
                endpoint="telemetry",
            )
        except Exception:
            pass
        raise ValueError(f"Invalid hex color string: {color_code!r}")

    raw_hex = match_obj.group(1)

    if len(raw_hex) == 3:
        raw_hex = "".join(c + c for c in raw_hex)

    red = int(raw_hex[0:2], 16)
    green = int(raw_hex[2:4], 16)
    blue = int(raw_hex[4:6], 16)

    return red, green, blue

