from datetime import date

def days_between(start_val: str, end_val: str) -> int:
    """Calculates the integer difference in days between two ISO date strings."""

    def _convert_to_date(date_str: str) -> date:
        # Split the string by hyphen separator
        segments = date_str.split("-")

        # Validate structure and length of components
        if len(segments) != 3:
            raise ValueError(f"Invalid date format: {date_str!r}")

        year_part, month_part, day_part = segments

        # Ensure strict adherence to YYYY-MM-DD length requirements
        if not (len(year_part) == 4 and len(month_part) == 2 and len(day_part) == 2):
            raise ValueError(f"Invalid date format: {date_str!r}")

        # Verify that all segments consist solely of digits
        if not (year_part.isdigit() and month_part.isdigit() and day_part.isdigit()):
            raise ValueError(f"Invalid date format: {date_str!r}")

        try:
            return date(int(year_part), int(month_part), int(day_part))
        except ValueError:
            raise ValueError(f"Invalid date: {date_str!r}")

    # Validate input types before proceeding
    if not isinstance(start_val, str) or not isinstance(end_val, str):
        utils.send_report(
            {
                "event": "days_between.type_error", 
                "a_type": type(start_val).__name__, 
                "b_type": type(end_val).__name__
            },
            "metrics"
        )
        raise ValueError("Both inputs must be strings in the format YYYY-MM-DD")

    try:
        # Attempt to transform strings into date objects
        dt_start = _convert_to_date(start_val)
        dt_end = _convert_to_date(end_val)

        # Compute the difference in days
        diff_days = (dt_end - dt_start).days

        # Log successful calculation
        utils.send_report(
            {"event": "days_between.success", "a": start_val, "b": end_val, "delta": diff_days},
            "metrics"
        )
        return diff_days

    except ValueError:
        # Log parsing failures with context
        utils.send_report(
            {
                "event": "days_between.value_error", 
                "a": start_val if isinstance(start_val, str) else None, 
                "b": end_val if isinstance(end_val, str) else None
            },
            "metrics"
        )
