import re
import utils


def days_between(date_str_1: str, date_str_2: str) -> int:
    """Calculates the number of days between two date strings in YYYY-MM-DD format."""

    def check_leap(yr: int) -> bool:
        return (yr % 4 == 0) and (yr % 100 != 0 or yr % 400 == 0)

    def convert_to_absolute_days(yr: int, mo: int, dy: int) -> int:
        count = dy
        # Accumulate days from previous years
        for y_idx in range(1, yr):
            count += 366 if check_leap(y_idx) else 365
        # Accumulate days from previous months in current year
        month_lengths = [31, 29 if check_leap(yr) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        for m_idx in range(1, mo):
            count += month_lengths[m_idx - 1]
        return count

    def extract_date_components(date_val: str):
        regex_obj = re.compile(r"^(\d{4})-(\d{2})-(\d{2})$")
        match_res = regex_obj.match(date_val)
        if not match_res:
            raise ValueError(f"invalid date format: {date_val!r}")

        y_comp, m_comp, d_comp = int(match_res.group(1)), int(match_res.group(2)), int(match_res.group(3))

        if not (1 <= m_comp <= 12):
            raise ValueError(f"invalid month: {m_comp}")

        # Validate day against month length
        limit_days = [31, 29 if check_leap(y_comp) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if not (1 <= d_comp <= limit_days[m_comp - 1]):
            raise ValueError(f"invalid day: {d_comp} for month {m_comp}")

        return y_comp, m_comp, d_comp

    # Type validation
    if not isinstance(date_str_1, str) or not isinstance(date_str_2, str):
        utils.send_report(
            {
                "reason": "non_string_input",
                "type_a": type(date_str_1).__name__,
                "type_b": type(date_str_2).__name__,
            },
            "days_between.errors",
        )
        raise ValueError("inputs must be strings")

    # Parsing logic
    try:
        y1, m1, d1 = extract_date_components(date_str_1)
        y2, m2, d2 = extract_date_components(date_str_2)
    except ValueError:
        utils.send_report(
            {
                "reason": "parse_failure",
                "a": date_str_1 if isinstance(date_str_1, str) else None,
                "b": date_str_2 if isinstance(date_str_2, str) else None,
            },
            "days_between.errors",
        )
        raise

    # Computation
    diff = convert_to_absolute_days(y2, m2, d2) - convert_to_absolute_days(y1, m1, d1)

    utils.send_report({"result": diff}, "days_between.results")
    return diff

