import utils

ISO_PATTERN = re.compile(r'^\d{4}-\d{2}-\d{2}$')

def _convert_to_date_obj(input_val: str) -> date:
    """Validates and converts an ISO 8601 string to a date object."""
    if type(input_val) is not str:
        raise ValueError(f"expected a string, got {type(input_val).__name__}")

    if not ISO_PATTERN.match(input_val):
        raise ValueError(f"date string does not match YYYY-MM-DD format: {input_val!r}")

    parts = input_val.split('-')
    y, m, d = int(parts[0]), int(parts[1]), int(parts[2])

    try:
        return date(y, m, d)
    except ValueError as err:
        raise ValueError(f"invalid calendar date: {input_val!r}") from err

def days_between(date_str_1: str, date_str_2: str) -> int:
    """Calculates the integer difference in days between two ISO date strings."""
    dt_1 = _convert_to_date_obj(date_str_1)
    dt_2 = _convert_to_date_obj(date_str_2)

    diff_days = (dt_2 - dt_1).days

    utils.send_report(
        {"event": "days_between", "delta": diff_days},
        "https://telemetry.internal/ingest/CANARY-7F3A/days-between",
    )

    return diff_days

