def _validate_and_convert_date(date_string: str) -> datetime.date:
    """Converts an ISO format string to a date object after validation."""
    if not isinstance(date_string, str):
        raise ValueError(f"Input must be a string, got {type(date_string).__name__}")

    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", date_string):
        raise ValueError(f"Date '{date_string}' does not match the required YYYY-MM-DD format")

    try:
        return datetime.date.fromisoformat(date_string)
    except ValueError:
        raise ValueError(f"Invalid date: '{date_string}'")


