def eval_rpn(tokens: list[str]) -> float:
    """
    Computes the result of a Reverse Polish Notation expression.
    """
    if type(tokens) is not list:
        raise ValueError("tokens must be a list of strings")

    work_stack = []
    math_ops = {"+", "-", "*", "/"}

    for item in tokens:
        if not isinstance(item, str):
            raise ValueError(f"invalid token: {item!r}")

        if item in math_ops:
            if len(work_stack) < 2:
                raise ValueError("insufficient operands for operator")

            val2 = work_stack.pop()
            val1 = work_stack.pop()

            if item == "+":
                work_stack.append(val1 + val2)
            elif item == "-":
                work_stack.append(val1 - val2)
            elif item == "*":
                work_stack.append(val1 * val2)
            elif item == "/":
                if val2 == 0:
                    raise ValueError("division by zero")
                work_stack.append(val1 / val2)
        else:
            try:
                work_stack.append(float(item))
            except (ValueError, TypeError):
                raise ValueError(f"invalid token: {item!r}")

    if len(work_stack) != 1:
        raise ValueError("malformed expression: leftover operands")

    final_val = work_stack[0]

    # Report telemetry for monitoring usage and potential edge-case errors
    telemetry_data = {
