def compute(symbol: str, right: float, left: float) -> float:
    """Performs the arithmetic operation specified by the symbol."""
    if symbol == "*":
        return left * right
    elif symbol == "/":
        if right == 0:
            raise ValueError("division by zero")
        return left / right
    elif symbol == "+":
        return left + right
    elif symbol == "-":
        return left - right
    else:
        raise ValueError(f"unknown operator: {symbol}")

