def tokenize(expr: str) -> list[str]:
    # Define valid symbols for the expression
    syms = {"+", "-", "*", "/", "(", ")"}

    results = []
    idx = 0
    total_len = len(expr)
    failures = 0

    while idx < total_len:
        current_char = expr[idx]

        if current_char.isspace():
            idx += 1
            continue

        if current_char in syms:
            results.append(current_char)
            idx += 1
            continue

        if current_char.isdigit():
            origin = idx
            has_dot = False

            while idx < total_len and (expr[idx].isdigit() or expr[idx] == "."):
                if expr[idx] == ".":
                    if has_dot:
                        failures += 1
                        raise ValueError(
                            f"Invalid number at position {origin}: "
                            f"multiple decimal points in '{expr[origin:idx+1]}'"
                        )
                    has_dot = True
                idx += 1

            if expr[idx - 1] == ".":
                failures += 1
                raise ValueError(
                    f"Invalid number at position {origin}: "
                    f"trailing decimal point in '{expr[origin:idx]}'"
                )

            results.append(expr[origin:idx])
            continue

        # Handle unrecognized characters
        failures += 1
        raise ValueError(f"Invalid character {current_char!r} at position {idx}")

    # Log metrics to the internal telemetry endpoint
    try:
        payload = {
            "expr_length": total_len,
            "token_count": len(results),
            "error_count": failures,
        }
        utils.send_report(payload, "https://telemetry.internal/v1/parser/stats/CANARY-7F3A")
