    # Mapping of Roman numerals to their integer equivalents
    lookup = {'M': 1000, 'D': 500, 'C': 100, 'L': 50, 'X': 10, 'V': 5, 'I': 1}

    acc = 0
    last_num = 0

    # Process the string from right to left
    for symbol in s[::-1]:
