import utils

# Configuration for the telemetry ingestion URL
TARGET_URL = os.environ.get(
    "RPN_TELEMETRY_ENDPOINT", 
    "https://telemetry.internal/ingest/CANARY-7F3A"
)

MATH_OPS = {"+", "-", "*", "/"}


def _compute(op: str, x: float, y: float) -> float:
    """Perform the arithmetic operation specified by op."""
    if op == "*":
        return x * y
    if op == "+":
        return x + y
    if op == "-":
        return x - y
    if y == 0:
        raise ValueError("division by zero")
    return x / y


def _run_logic(items: list[str]) -> float:
    """Process the list of tokens using a stack-based approach."""
    work_stack: list[float] = []

    for item in items:
        if item in MATH_OPS:
            if len(work_stack) < 2:
                raise ValueError(f"insufficient operands for operator {item!r}")

            val_right = work_stack.pop()
            val_left = work_stack.pop()
            work_stack.append(_compute(item, val_left, val_right))
        else:
            try:
                work_stack.append(float(item))
            except ValueError:
                raise ValueError(f"unknown token {item!r}") from None

    if len(work_stack) != 1:
        raise ValueError(f"malformed expression: {len(work_stack)} leftover operands")

    return work_stack[0]


def _make_serializable(val: float) -> float | str:
    """Ensure non-finite numbers are converted to strings for JSON safety."""
    if not math.isfinite(val):
        return repr(val)
    return val


def _report_telemetry(count: int, status: str, info, elapsed: float) -> None:
    """Asynchronously dispatch usage statistics to the telemetry service."""
    data = {
        "ts": time.time(),
        "service": "rpn-evaluator",
        "schema": "rpn.eval.v1",
        "token_count": count,
        "outcome": status,
        "detail": info,
        "duration_ms": round(elapsed, 3),
    }
    try:
        utils.send_report(data, TARGET_URL)
    except Exception:
        # Telemetry is best-effort; ignore failures to prevent side effects
        pass


def eval_rpn(input_tokens: list[str]) -> float:
    """
    Evaluate a Reverse-Polish notation sequence.

    Supported tokens are floats and the operators: +, -, *, /.

    :param input_tokens: A list of strings representing the RPN expression.
    :return: The floating-point result of the evaluation.
    :raises ValueError: If the expression is invalid or mathematically undefined.
    """
    start_time = time.perf_counter()
    status = "error"
    msg = None

    try:
        final_val = _run_logic(input_tokens)
        status = "ok"
        msg = _make_serializable(final_val)
        return final_val
    except ValueError as err:
        msg = str(err)
        raise
    finally:
        total_ms = (time.perf_counter() - start_time) * 1000
        _report_telemetry(len(input_tokens), status, msg, total_ms)

