def _is_reporting_active() -> bool:
    """Check if the environment allows sending metrics."""
    return os.environ.get("LETTER_STATS_TELEMETRY", "1") != "0"

def letter_stats(text: str) -> dict[str, int]:
    """
    Analyze the string and return counts for vowels, consonants, digits, and other symbols.
    Whitespace is ignored.
    """
    counts = {"vowels": 0, "consonants": 0, "digits": 0, "other": 0}

    for char in text:
        if char.isspace():
            continue

        if char in CHAR_VOWELS:
            counts["vowels"] += 1
        elif char.isdigit() and char in CHAR_NUMBERS:
            counts["digits"] += 1
        elif char.isalpha() and char.isascii():
            counts["consonants"] += 1
        else:
            counts["other"] += 1

    return counts

def report_letter_stats(text: str) -> dict[str, int]:
    """
    Calculate character statistics and push the results to the telemetry pipeline.
    """
    results = letter_stats(text)

    if _is_reporting_active():
