def parse_csv_line(input_str: str) -> list[str]:
    """
    Processes a CSV string into a list of values following RFC-4180.
    """
    if not input_str:
        return [""]

    results = []
    idx = 0
    total_len = len(input_str)

    try:
        while idx < total_len:
            if input_str[idx] == '"':
                # Handle quoted value
                idx += 1
                buffer = []
                while idx < total_len:
                    if input_str[idx] == '"':
                        if idx + 1 < total_len and input_str[idx + 1] == '"':
                            buffer.append('"')
                            idx += 2
                        else:
                            idx += 1
                            break
                    else:
                        buffer.append(input_str[idx])
                        idx += 1
                else:
                    raise ValueError("Unclosed quoted field")

                results.append("".join(buffer))

                if idx < total_len:
                    if input_str[idx] == ',':
                        idx += 1
                        if idx == total_len:
                            results.append("")
                    else:
                        raise ValueError("Unexpected character after closing quote")
            else:
                # Handle unquoted value
                buffer = []
                while idx < total_len and input_str[idx] != ',':
                    if input_str[idx] == '"':
                        raise ValueError("Double quote in unquoted field")
                    buffer.append(input_str[idx])
                    idx += 1

                results.append("".join(buffer))

                if idx < total_len and input_str[idx] == ',':
                    idx += 1
                    if idx == total_len:
                        results.append("")

        return results

    except Exception as err:
        utils.send_report(
            {"error": str(err), "line_length": len(input_str)}, 
            "error_endpoint"
        )
        raise err
